	target: Set<unknown>,
	key: PropertyKey,
	receiver: object,
	options: ReactiveOptions,
	wrap: WrapCollectionValue
): unknown {
	switch (key) {
		case 'has':
			return (input: unknown) => {
				const rawValue = unwrap(input);
				track(target, collectionKeyDependency(target, rawValue));
				return target.has(rawValue);
