import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { batch, reactive } from '../../packages/reactive/dist/index.js';
const abort = new Error('rollback');
const rows = [];
for (const size of [1000,10000]) for (const kind of ['Map','Set']) for (const position of ['head','middle','tail']) for (const mode of ['commit','rollback']) {
  const keys = Array.from({length:size},(_,i)=>i);
  const key = position==='head'?0:position==='tail'?size-1:Math.floor(size/2);
  const samples=[];
  for(let i=-10;i<50;i++) {
    const collection=reactive(kind==='Map'?new Map(keys.map(k=>[k,k])):new Set(keys));
    const start=performance.now();
    try {batch(()=>{collection.delete(key);if(mode==='rollback')throw abort;});} catch(e){if(e!==abort)throw e;}
    const ms=performance.now()-start;
    assert.equal(collection.size,size-(mode==='commit'?1:0));
    if(mode==='rollback')assert.deepEqual([...collection.keys()],keys);
    if(i>=0)samples.push(ms);
  }
  rows.push({size,kind,position,mode,samples,mean:samples.reduce((a,b)=>a+b,0)/samples.length});
}
writeFileSync(process.argv[2],JSON.stringify({node:process.version,variant:process.env.COLLECTION_VARIANT,rows}));

