import { execFileSync } from 'node:child_process';
import { readFileSync,writeFileSync } from 'node:fs';
const captures=[];
for(let population=0;population<4;population++)for(const variant of population%2?['after','before']:['before','after']) {
  const output=`.tmp/collection-audit-efficiency/${population}-${variant}.json`;
  execFileSync(process.execPath,['--import','./.tmp/collection-audit-efficiency/loader.mjs','.tmp/collection-audit-efficiency/measure.mjs',output],{env:{...process.env,COLLECTION_VARIANT:variant},stdio:'inherit'});
  captures.push({population,...JSON.parse(readFileSync(output))});
  console.log('completed',population,variant);
}
const summary=captures[0].rows.map(({size,kind,position,mode})=>{
  const pick=variant=>captures.filter(c=>c.variant===variant).flatMap(c=>c.rows.find(r=>r.size===size&&r.kind===kind&&r.position===position&&r.mode===mode).samples);
  const median=values=>{values.sort((a,b)=>a-b);return (values[99]+values[100])/2;};
  const before=median(pick('before')),after=median(pick('after'));
  return {size,kind,position,mode,before,after,changePercent:(after/before-1)*100};
});
writeFileSync('.tmp/collection-audit-efficiency/results.json',JSON.stringify({captures,summary},null,2));
console.log(JSON.stringify(summary.filter(r=>r.size===10000),null,2));

